import React,{useRef} from 'react'; import Card from './Card'; import LandscapeCard from './LandscapeCard'; import {FaAngleLeft,FaAngleRight} from 'react-icons/fa6'; import SectionHeader from '../ui/SectionHeader'; import IconButton from '../ui/IconButton'; import Skeleton from '../ui/Skeleton'; import ErrorState from '../ui/ErrorState'; import EmptyState from '../ui/EmptyState';
const HorizontalScrollCard=({data=[],heading,trending,media_type,variant='poster',loading=false,error=null,onRetry})=>{const containerRef=useRef(null);const scrollBy=distance=>containerRef.current?.scrollBy({left:distance,behavior:'smooth'});const isLandscape=variant==='landscape';return <section className='container mx-auto my-10 px-4 lg:px-10'><SectionHeader title={heading}/>{loading?<div className='grid grid-flow-col gap-4 overflow-hidden'>{Array.from({length:isLandscape?4:6}).map((_,i)=><Skeleton key={i} className={isLandscape?'h-52 w-[360px]':'h-80 w-[230px]'}/>)}</div>:null}{!loading&&error?<ErrorState message={`Unable to load ${heading.toLowerCase()}.`} onRetry={onRetry}/>:null}{!loading&&!error&&!data.length?<EmptyState title={`No ${heading.toLowerCase()} available`} message='There is no content to show in this section right now.'/>:null}{!loading&&!error&&data.length?<div className='relative'><div ref={containerRef} className={`scrollBar-none relative z-10 grid grid-flow-col gap-4 overflow-x-auto scroll-smooth ${isLandscape?'grid-cols-[repeat(auto-fit,300px)] sm:grid-cols-[repeat(auto-fit,360px)]':'grid-cols-[repeat(auto-fit,230px)]'}`}>{data.map((item,index)=>isLandscape?<LandscapeCard key={`${item.id}-${heading}-${index}`} data={item} media_type={media_type}/>:<Card key={`${item.id}-${heading}-${index}`} data={item} index={index+1} trending={trending} media_type={media_type}/>)}</div><div className='pointer-events-none absolute inset-0 hidden items-center justify-between lg:flex'><IconButton onClick={()=>scrollBy(-500)} className='pointer-events-auto -ml-5 shadow-xl' aria-label={`Scroll ${heading} left`}><FaAngleLeft/></IconButton><IconButton onClick={()=>scrollBy(500)} className='pointer-events-auto -mr-5 shadow-xl' aria-label={`Scroll ${heading} right`}><FaAngleRight/></IconButton></div></div>:null}</section>;}; export default HorizontalScrollCard;
